	if (has(m, TradeConditionBit::OPENED)) append("K");
	if (has(m, TradeConditionBit::SELLER)) append("L");
	if (has(m, TradeConditionBit::SOLD)) append("M");
	if (has(m, TradeConditionBit::STOPPED_STOCK)) append("N");
	if (pos > 0) buf[pos-1] = '\0'; else if (cap > 0) buf[0] = '\0';
