[[nodiscard]] inline bool parse_SecurityTradingStatus(const char *s, SecurityTradingStatus &out) noexcept {
	if (!s) return false;
	if (std::strcmp(s, "1") == 0) { out = SecurityTradingStatus::OPENING_DELAY; return true; }
	if (std::strcmp(s, "10") == 0) { out = SecurityTradingStatus::MARKET_ON_CLOSE_IMBALANCE_SELL; return true; }
	if (std::strcmp(s, "12") == 0) { out = SecurityTradingStatus::NO_MARKET_IMBALANCE; return true; }
	if (std::strcmp(s, "13") == 0) { out = SecurityTradingStatus::NO_MARKET_ON_CLOSE_IMBALANCE; return true; }
	if (std::strcmp(s, "14") == 0) { out = SecurityTradingStatus::ITS_PRE_OPENING; return true; }
	if (std::strcmp(s, "15") == 0) { out = SecurityTradingStatus::NEW_PRICE_INDICATION; return true; }
	if (std::strcmp(s, "16") == 0) { out = SecurityTradingStatus::TRADE_DISSEMINATION_TIME; return true; }
	if (std::strcmp(s, "17") == 0) { out = SecurityTradingStatus::READY_TO_TRADE; return true; }
	if (std::strcmp(s, "18") == 0) { out = SecurityTradingStatus::NOT_AVAILABLE_FOR_TRADING; return true; }
	if (std::strcmp(s, "19") == 0) { out = SecurityTradingStatus::NOT_TRADED_ON_THIS_MARKET; return true; }
	if (std::strcmp(s, "2") == 0) { out = SecurityTradingStatus::TRADING_HALT; return true; }
	if (std::strcmp(s, "20") == 0) { out = SecurityTradingStatus::UNKNOWN_OR_INVALID; return true; }
	if (std::strcmp(s, "3") == 0) { out = SecurityTradingStatus::RESUME; return true; }
	if (std::strcmp(s, "4") == 0) { out = SecurityTradingStatus::NO_OPEN; return true; }
	if (std::strcmp(s, "5") == 0) { out = SecurityTradingStatus::PRICE_INDICATION; return true; }
	if (std::strcmp(s, "6") == 0) { out = SecurityTradingStatus::TRADING_RANGE_INDICATION; return true; }
	if (std::strcmp(s, "7") == 0) { out = SecurityTradingStatus::MARKET_IMBALANCE_BUY; return true; }
	if (std::strcmp(s, "8") == 0) { out = SecurityTradingStatus::MARKET_IMBALANCE_SELL; return true; }
	if (std::strcmp(s, "9") == 0) { out = SecurityTradingStatus::MARKET_ON_CLOSE_IMBALANCE_BUY; return true; }
	return false;
}

